import azure.cognitiveservices.speech as speechsdk
import os

def handle_partial_and_final_results(speech_recognizer: speechsdk.SpeechRecognizer):
    def recognizing_handler(evt):
        if evt.result.reason == speechsdk.ResultReason.RecognizingSpeech:
            print(f"PARTIAL: {evt.result.text}")

    def recognized_handler(evt):
        if evt.result.reason == speechsdk.ResultReason.RecognizedSpeech:
            print(f"FINAL: {evt.result.text}")
        elif evt.result.reason == speechsdk.ResultReason.NoMatch:
            print(f"NOMATCH: Speech could not be recognized.")

    speech_recognizer.recognizing.connect(recognizing_handler)
    speech_recognizer.recognized.connect(recognized_handler)

import azure.cognitiveservices.speech as speechsdk
import os

def get_speech_config(language: str = "en-US"):    
    speech_key = os.environ.get("AZURE_SPEECH_KEY")
    service_region = os.environ.get("AZURE_SPEECH_REGION")
    if not speech_key or not service_region:
        raise ValueError("AZURE_SPEECH_KEY and AZURE_SPEECH_REGION environment variables must be set.")
    speech_config = speechsdk.SpeechConfig(subscription=speech_key, region=service_region)
    speech_config.speech_recognition_language = language
    return speech_config

def get_audio_config_from_microphone():
    return speechsdk.AudioConfig(use_default_microphone=True)

def get_push_audio_input_stream_config():
    return speechsdk.AudioConfig(stream=speechsdk.audio.PushAudioInputStream())

from dataclasses import dataclass
import azure.cognitiveservices.speech as speechsdk

@dataclass
class TranscriptEvent:
    type: str  # "recognizing" or "recognized"
    text: str

def normalize_speech_recognition_result(result: speechsdk.SpeechRecognitionResult) -> TranscriptEvent | None:
    if result.reason == speechsdk.ResultReason.RecognizingSpeech:
        return TranscriptEvent(type="recognizing", text=result.text)
    elif result.reason == speechsdk.ResultReason.RecognizedSpeech:
        return TranscriptEvent(type="recognized", text=result.text)
    elif result.reason == speechsdk.ResultReason.NoMatch:
        return TranscriptEvent(type="recognized", text="") # No match, return empty text for final
    return None

from google.cloud import translate
import os

def translate_caption(text: str, target_language_code: str = "es") -> str:
    client = translate.TranslationServiceClient()
    project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
    if not project_id:
        raise ValueError("GOOGLE_CLOUD_PROJECT_ID environment variable must be set.")
    parent = f"projects/{project_id}"

    response = client.translate_text(
        request={
            "parent": parent,
            "contents": [text],
            "mime_type": "text/plain",  # Mime types: "text/plain", "text/html"
            "target_language_code": target_language_code,
        }
    )

    translated_text = ""
    for translation in response.translations:
        translated_text += translation.translated_text
    return translated_text
